  card.querySelector('.edit').onclick = () => openModal(bm);
  card.querySelector('.del').onclick = async () => {
    if (confirm(`Delete “${bm.title}”?`)) {
      await api(`/api/bookmarks/${bm.id}`, { method: 'DELETE' });
      refresh();
