.tag-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.tag-list li button {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 12px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 13px;
}
.tag-list li button:hover { background: var(--surface-2); color: var(--text); }
.tag-list li button.active { background: var(--surface-2); color: var(--accent); }
.tag-count { font-size: 11px; background: var(--surface-2); border-radius: 10px; padding: 1px 8px; }
.tag-list li button.active .tag-count { background: rgba(91,141,239,.2); }

.content { flex: 1; padding: 20px 24px 60px; min-height: calc(100vh - 64px); }
.active-filter-bar {
  margin-bottom: 16px;
  color: var(--muted);
  font-size: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.active-filter-bar .clear { color: var(--accent); cursor: pointer; text-decoration: none; }

.bookmark-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 16px;
}

.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.card-title { display: flex; align-items: center; gap: 8px; min-width: 0; }
.card-title img { width: 18px; height: 18px; border-radius: 4px; flex-shrink: 0; }
.card-title a {
  font-weight: 600;
  color: var(--text);
  text-decoration: none;
  font-size: 15px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.card-title a:hover { color: var(--accent); }
.star-btn { background: none; border: none; cursor: pointer; font-size: 18px; color: var(--border); padding: 0; line-height: 1; }
.star-btn.on { color: var(--star); }
.card-url { font-size: 12px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-url a { color: var(--muted); text-decoration: none; }
.card-url a:hover { text-decoration: underline; }
.card-desc { font-size: 13px; color: #c3c8d2; }
.card-tags { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  font-size: 11px;
  background: var(--surface-2);
  color: var(--muted);
  padding: 3px 9px;
  border-radius: 20px;
  cursor: pointer;
  border: none;
}
.chip:hover { color: var(--accent); }
.card-actions { display: flex; gap: 8px; margin-top: 4px; }
.card-actions button {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 6px;
}
.card-actions button:hover { background: var(--surface-2); color: var(--text); }
.card-actions .del:hover { color: var(--danger); }

.empty-state { text-align: center; padding: 80px 20px; color: var(--muted); }
.empty-state h3 { color: var(--text); margin-bottom: 8px; }

.modal-backdrop {
  position: fixed; inset: 0;
  background: rgba(0,0,0,.6);
  display: flex; align-items: center; justify-content: center;
  z-index: 100; padding: 20px;
}
.modal {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 24px;
  width: 100%; max-width: 480px;
  max-height: 90vh; overflow-y: auto;
}
.modal h2 { margin-top: 0; }
#bookmark-form { display: flex; flex-direction: column; gap: 14px; }
#bookmark-form label { display: flex; flex-direction: column; gap: 6px; font-size: 13px; color: var(--muted); }
#bookmark-form input[type=text], #bookmark-form textarea {
  padding: 10px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  resize: vertical;
}
#bookmark-form input:focus, #bookmark-form textarea:focus { outline: 2px solid var(--accent); border-color: transparent; }
.hint { color: var(--border); }
.checkbox { flex-direction: row !important; align-items: center; color: var(--text) !important; }
.checkbox input { width: auto; }
.form-errors {
  background: rgba(224,91,107,.12);
  border: 1px solid rgba(224,91,107,.4);
  color: #f0a5ae;
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 13px;
}
.form-errors ul { margin: 0; padding-left: 18px; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 6px; }

@media (max-width: 720px) {
  .sidebar { display: none; }
  .topbar { flex-wrap: wrap; }
}
